/** The compact Talk Show facts block Jewel receives each turn (talk kind only). */
function talkShowContextBlock(project: any): Record<string, unknown> | undefined {
  if (!project || project.kind !== "talk") return undefined;
  const sign = findSignAsset(project);
  const prompt = promptAsset(project);
  const tools = Array.isArray(project.gameTools) ? project.gameTools : [];
  const assets = Array.isArray(project.assets) ? project.assets : [];
  return {
    showName: typeof project.name === "string" ? project.name : "",
    themeStyle: typeof project.gamePlan?.theme === "string" ? project.gamePlan.theme : "",
    signPresent: Boolean(sign),
    signAsset: sign ? (sign.storageKey || sign.name) : null,
    backdropCount: backgroundAssets(project).length,
    promptSet: Boolean(prompt),
    promptText: prompt ? (assetPromptText(prompt)?.text || "") : "",
    researched: project.workflowProgress?.researched === true,
    quizQuestions: tools.reduce((total: number, tool: any) => total + quizQuestionsOf(tool).length, 0),
    followUpTools: tools.filter((tool: any) => tool?.enabled && (tool.type === "question-card" || tool.type === "card-list")).length,
    youtubeAdded: tools.some((tool: any) => tool?.type === "youtube" && tool.enabled),
    mediaCount: assets.filter((asset: any) => asset?.role !== "background" && (asset?.storageKey || asset?.url)).length,
    skippedAreas: Array.isArray(project.workflowProgress?.skipped) ? project.workflowProgress.skipped : [],
    deckSize: Array.isArray(project.talkDeck) ? project.talkDeck.length : 0,
    // Set the Stage (2026-11-04): the deck's moments, in the
    // creator's order, each with what it points at (ref) and whether
    // it is staged yet — a moment is staged when its clicker already
    // exists on the dashboard (media, quiz, youtube, composition) or,
    // for the sign and backdrop, when it already IS the overlay's
    // opening scene. Same definition the review page shows.
    deckMoments: Array.isArray(project.talkDeck) ? project.talkDeck.map((slide: any) => ({ kind: slide?.kind, label: slide?.label, ref: slide?.refKey || null, staged: deckMomentStaged(project, slide) })) : [],
  };
}

