export const maxDuration = 180;

export async function GET() {
  return NextResponse.json({ configured: museConfigured() || assistantConfigured() });
}

/**
 * City Crime Scene is scoped to the project owner: when the acted-on project
 * is stored, its owner must also be entitled. Returns null when no stored
 * project row exists (a new unsaved draft) or ownership cannot be checked, so
 * the acting user's own entitlement governs.
 */
async function storedProjectOwnerCcssEntitled(projectId: string): Promise<boolean | null> {
  try {
    const db = getDb();
    if (!db) return null;
    const rows = await db`SELECT owner_id FROM projects WHERE id = ${projectId} OR slug = ${projectId} LIMIT 1`;
    if (!rows.length) return null;
    const ownerId = rows[0].owner_id ? String(rows[0].owner_id) : null;
    if (!ownerId) return false;
    const ownerUsers = await db`SELECT email FROM neon_auth.user WHERE id = ${ownerId} LIMIT 1`;
    return canUseCityCrimeScene(ownerUsers[0]?.email ? String(ownerUsers[0].email) : null);
  } catch {
    return null;
  }
}

export async function POST(request: Request) {
  if (!museConfigured() && !assistantConfigured()) return NextResponse.json({ configured: false, error: "META_API_KEY is not configured." }, { status: 503 });
  const body = await request.json();
  if (Array.isArray(body.searchEvidence)) body.searchEvidence = body.searchEvidence.map((source: any, sourceId: number) => ({ ...source, sourceId }));
  // City Crime Scene is restricted to select accounts — and scoped to the
  // PROJECT OWNER: an entitled account acting in someone else's stored project
  // does not unlock it there. A project that is not stored yet (new unsaved
  // draft) is governed by the acting user's own entitlement.
  const aiUser = await requireCreator().catch(() => null);
  let ccssEntitled = canUseCityCrimeScene(aiUser?.email);
  if (ccssEntitled) {
    const actedProjectId = typeof body.project?.id === "string" ? body.project.id : "";
    if (actedProjectId && (await storedProjectOwnerCcssEntitled(actedProjectId)) === false) ccssEntitled = false;
  }
  const draftSystemBase = ccssEntitled
    ? DRAFT_SYSTEM + `\nCity Crime Scene (tool type "city-crime-scene") is an improv whodunnit mystery game builder available to this user. When they mention mysteries, crimes, detective games, or whodunnits — or ask what you can build — proactively offer to create a City Crime Scene game. Create it with changes.newTools [{type:"city-crime-scene",name,config:{},connect:true}]; the dedicated editor opens for full customization.
Editing this user's existing City Crime Scene case: use changes.gameTools [{id:"the existing city-crime-scene tool id",config:{mystery:PATCH}}]. PATCH is a partial case — include ONLY the items and fields you are changing. Scalar fields (title, premise, crime, victim, backstory, plot, suspectCount, detectiveCount, interrogationSeconds, courtroomSeconds) replace when included. Collections (locations, clues, flashbacks, suspects, witnesses, helperWitnesses, timeline, twists) match by each item's existing id: include an item's id plus only its changed fields — every other field and every other item is preserved exactly; an item with a new unique id is added to the case. Keep the case coherent or the edit is refused: exactly one suspect may be guilty (marking one suspect guilty in your patch automatically clears the others), every suspect keeps a motive and an alibi, and a clue's summary stays GENERALIZED — the specific detail lives only in its description, revealed during play. Host-only truth (isGuilty, actualCrimeDetails, twists, demeanor, tells, extraInfo, questions) belongs in the case file only: never name the guilty party or quote the actual crime details in your reply.
Attaching media to the case: media already saved in this project attaches by setting the item's media key field in a mystery patch to the asset's exact storageKey — location imageKey; clue cutSceneVideoKey or audioKey; suspect guideVideoKey; flashback videoKey; helper portraitKey or videoKey (a helper's mediaKey is the host's own uploaded reference and is never overwritten by generation). To create NEW media for a case item, return the media generation action AND add "ccssAttach":{"toolId":"the city-crime-scene tool id","kind":"location"|"clue"|"suspect"|"flashback"|"helper","itemId":"the item's existing id","field":"the media key field"}: the app generates the media, saves it to the project, and attaches it to that item automatically — never claim it is attached before that happens. Match the media type to the field: image for imageKey/portraitKey, video for cutSceneVideoKey/guideVideoKey/videoKey, voice or sfx for audioKey. For a helper who has an uploaded reference (mediaKey), pass that asset's exact storageKey as the action's sourceKey so the portrait or video is generated from the host's own media.`
    : DRAFT_SYSTEM + `\nCity Crime Scene (tool type "city-crime-scene") is a restricted feature available only to select accounts. This user does not have access. Never create a city-crime-scene tool, never edit one, and never attach media to one. If the user asks for it, explain briefly that it is not available for their account.`;
  const templateInfo = body.project?.templateId ? getGameTemplate(body.project.templateId) : undefined;
  const templateNote = templateInfo ? `\nThis project was started from the "${templateInfo.name}" game template. ${templateInfo.description} When the user asks to customize it, help them modify the template's questions, content, styling, rules, or structure. You can edit any part of the template.` : "";
  const rawFeedback = body.generationFeedback && typeof body.generationFeedback === "object" ? body.generationFeedback : null;
  const generationFeedback = rawFeedback && typeof rawFeedback.kind === "string" && typeof rawFeedback.prompt === "string"
    ? { kind: rawFeedback.kind.slice(0, 40), prompt: rawFeedback.prompt.slice(0, 2000), error: typeof rawFeedback.error === "string" ? rawFeedback.error.slice(0, 500) : "" }
    : undefined;
  const rawEditResult = body.editResult && typeof body.editResult === "object" ? body.editResult : null;
  const editResult = rawEditResult && typeof rawEditResult.sourceKey === "string" && typeof rawEditResult.prompt === "string" && typeof rawEditResult.resultKey === "string"
    ? { sourceKey: rawEditResult.sourceKey.slice(0, 300), prompt: rawEditResult.prompt.slice(0, 3000), resultKey: rawEditResult.resultKey.slice(0, 300), resultName: typeof rawEditResult.resultName === "string" && rawEditResult.resultName ? rawEditResult.resultName.slice(0, 300) : rawEditResult.resultKey.slice(0, 300), layer: Number.isInteger(rawEditResult.layer) ? Math.min(5, Math.max(1, rawEditResult.layer)) : 1 }
    : undefined;
  const talkShow = talkShowContextBlock(body.project);
  const stageReview = body.workspaceStage === "build" && (body.project?.kind === "gameshow" || body.project?.kind === "talk") ? JEWEL_STAGE_REVIEW_ADDENDUM : "";
  const draftSystem = draftSystemBase + templateNote + JEWEL_ADDENDUM + JEWEL_LAYERING_ADDENDUM + JEWEL_WORKFLOW_ADDENDUM + JEWEL_GENERATION_ADDENDUM + (talkShow ? JEWEL_TALKSHOW_ADDENDUM : "") + stageReview + (generationFeedback ? JEWEL_FEEDBACK_ADDENDUM : "") + (editResult ? JEWEL_EDIT_RESULT_ADDENDUM : "");
  // Jewel's progress awareness: the workflow model, computed from the
  // project's real data on every turn (see lib/workflow-progress.ts).
  const workflowEvaluation = body.project ? evaluateWorkflow(body.project) : undefined;
  const draftContext = {
    request: body.request, recentConversation: Array.isArray(body.history) ? body.history.slice(-10) : [], project: body.project,
    selectedImageKey: body.selectedImageKey, selectedAssetKey: body.selectedAssetKey, workspaceStage: body.workspaceStage,
    selectedItem: body.selectedItem, searchEvidence: body.searchEvidence,
    workflowProgress: workflowEvaluation ? workflowContextBlock(workflowEvaluation) : undefined,
    ...(talkShow ? { talkShow } : {}),
    executionGuide: body.project ? executionContext(body.project) : undefined,
    backgroundVisual: checkedBackgroundContext(body.backgroundVisual),
    ...(generationFeedback ? { generationFeedback } : {}),
    ...(editResult ? { editResult } : {}),
  };
  if (!adviceOnlyRequest(String(body.request || "")) && body.project?.gameTools && body.project?.controls) { const timer = timerControlRequest(String(body.request || ""), body.history, body.project, body.selectedItem); if (timer) return NextResponse.json({ configured: true, ...timer }); const cycle = coinCycleRequest(String(body.request || ""), body.history, body.project, body.selectedItem); if (cycle) return NextResponse.json({ configured: true, ...cycle }); }
  // Every model call goes through this helper: Muse first, and when Muse
  // cannot produce a message (not configured, unreachable, or any provider
  // HTTP failure) the original AI chat provider answers with the same
  // messages instead, so a Muse outage never leaves the creator unserved.
  // A Muse credit failure still alerts the admin — once per request, as
  // before — even when the fallback goes on to serve the creator. When the
  // fallback cannot produce a message either, the original Muse failure is
  // rethrown so the error responses below keep their exact prior meaning.
  let creditAlertSent = false;
  const jewelChatCompletion = async (
    completionMessages: { role: "system" | "user" | "assistant"; content: string }[],
    completionOptions: { jsonObject: boolean; temperature: number; maxTokens: number; timeoutMs: number },
  ): Promise<string> => {
    let museError: unknown = null;
    if (museConfigured()) {
      try {
        return await museChatCompletion(completionMessages, completionOptions);
      } catch (error) {
        museError = error;
        if (!creditAlertSent && error instanceof MuseApiError) {
          const providerMessage = error.providerMessage || error.message;
          if (isCreditError(error.status, String(providerMessage))) {
            creditAlertSent = true;
            await notifyAdminOfCreditIssue("jewel/muse", `Muse request failed (HTTP ${error.status || "unknown"}): ${providerMessage}`);
          }
        }
      }
    }
    if (assistantConfigured()) {
      try {
        const fallbackMessage = await assistantChatCompletion(completionMessages, completionOptions);
        if (fallbackMessage) return fallbackMessage;
      } catch { /* the original Muse failure below decides the response */ }
    }
    if (museError) throw museError;
    throw new MuseApiError("META_API_KEY is not configured.", 503);
  };
  let message = "";
  try {
    message = await jewelChatCompletion(
      [{ role: "system", content: draftSystem }, { role: "user", content: JSON.stringify(draftContext) }],
      { jsonObject: true, temperature: 0.3, maxTokens: 16384, timeoutMs: 85000 },
    );
  } catch (error) {
    if (error instanceof MuseConnectionError) return NextResponse.json({ configured: true, error: "The AI service did not respond in time. No changes were made. Please try your request again." }, { status: 504 });
    if (error instanceof MuseApiError) {
      const providerMessage = error.providerMessage || error.message;
      if (isCreditError(error.status, String(providerMessage))) {
        return NextResponse.json({ configured: true, error: "The AI assistant is temporarily unavailable. The site administrator has been notified. No changes were made." }, { status: 502 });
      }
      return NextResponse.json({ configured: true, error: `Jewel request failed: ${providerMessage}` }, { status: error.status || 502 });
    }
    throw error;
  }
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const stripped = String(message).trim().replace(/^```(?:json)?\s*|\s*```$/g, "");
      const first = stripped.indexOf("{"), last = stripped.lastIndexOf("}");
      const clean = first >= 0 && last > first ? stripped.slice(first, last + 1) : stripped;
      const parsed = JSON.parse(clean);
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("Return one JSON object, not a list or text.");
      parsed.changes = normalizeDraftChanges(parsed.changes);
      if (!ccssEntitled) {
        const wantsCcss = (parsed.action?.type === "tool" && parsed.action?.toolType === "city-crime-scene")
          || (Array.isArray(parsed.changes?.newTools) && parsed.changes.newTools.some((t: any) => t?.type === "city-crime-scene"))
          || (Array.isArray(parsed.changes?.gameTools) && parsed.changes.gameTools.some((t: any) => t?.id && (body.project?.gameTools || []).some((existing: any) => existing.id === t.id && existing.type === "city-crime-scene")))
          || (parsed.action && typeof parsed.action === "object" && (parsed.action as any).ccssAttach);
        if (wantsCcss) throw new Error("City Crime Scene is only available to select accounts and is not enabled for this account.");
      }
      validateExplicitSettings(String(body.request || ""), parsed);
      validateSavedReferences(body.project, parsed.changes);
      validateRequestedTargets(String(body.request || ""), body.project, parsed.changes);
      validateRequestedAutomation(String(body.request || ""), parsed.changes);
      validateSequenceAdditions(String(body.request || ""), parsed.changes, parsed.action);
      validateCompletionClaim(parsed);
      if (adviceOnlyRequest(String(body.request || "")) && (parsed.action || Object.keys(parsed.changes).length)) throw new Error("This request is for advice or suggestions only. Return useful suggestions in reply, changes {}, action null. Wait for the user to ask for implementation.");
      const raw = parsed.action;
      const mediaAction = checkedAssistantMediaAction(raw, body.project?.assets || []);
      // Generation actions are checked by lib/jewel-generation.ts: the same
      // option set (and the same validation) the manual generator panels
      // offer, so nothing a panel can do is lost when Jewel carries it.
      let action: any = mediaAction
        || (raw?.type === "search" && typeof raw.query === "string" && raw.query.trim() && !body.searchEvidence
          ? { type: "search", query: raw.query.trim().slice(0, 200) }
          : null)
        || checkedTriviaAction(raw)
        || checkedBoardRegenerateAction(raw, body.project)
        || (raw?.type === "tool" && creatableTools.includes(raw.toolType)
          ? { type: "tool", toolType: raw.toolType, name: typeof raw.name === "string" ? raw.name.slice(0, 80) : "", config: raw.config && typeof raw.config === "object" && !Array.isArray(raw.config) ? raw.config : {} }
          : null)
        || checkedGenerationAction(raw, String(body.request || ""));
      // Generation feedback guard: an identical resubmission of the failed
      // generation is never useful. On the first attempt it is a validation
      // error (Muse gets one chance to adjust); if it comes back identical
      // again, drop the action and surface the explanation instead.
      if (generationFeedback && action && ["image", "video", "voice", "music", "sfx"].includes(action.type) && action.type === generationFeedback.kind && "prompt" in action && typeof action.prompt === "string" && action.prompt.trim() === generationFeedback.prompt.trim()) {
        if (attempt === 0) throw new Error("That exact generation already failed. Adjust the approach: rewrite or simplify the prompt, change the length or wording, offer an image as a motion-treated still when a video failed, or explain in reply with action null. Never resubmit the identical request.");
        action = null;
      }
      // City Crime Scene media attachment: an entitled user's media action
      // may name the case item its finished media belongs to. The target is
      // validated against the actual draft here (saved IDs only, never a
      // URL); the client executor performs the attachment once the generation
      // has been saved to the project.
      const rawAttach = raw && typeof raw === "object" ? (raw as any).ccssAttach : undefined;
      if (rawAttach !== undefined && rawAttach !== null) {
        if (!ccssEntitled) throw new Error("City Crime Scene is only available to select accounts and is not enabled for this account.");
        if (!action || !["image", "video", "voice", "music", "sfx"].includes(action.type)) throw new Error("Attaching new media to the case requires a media generation action in the same response.");
        const attach = checkedCcssAttach(rawAttach, body.project);
        const actionKind = action.type === "image" ? "image" : action.type === "video" ? "video" : (action.type === "voice" || action.type === "sfx") ? "audio" : "";
        if (attach.mediaKind !== actionKind) throw new Error(`That case field holds a ${attach.mediaKind}, so generate a ${attach.mediaKind} for it instead.`);
        (action as any).ccssAttach = { toolId: attach.toolId, kind: attach.kind, itemId: attach.itemId, field: attach.field };
      }
      // Safety net: the user asked for an original song but the assistant returned no music action
      // (e.g. it deflected to the manual Lyrics field). Force a retry with explicit instructions.
      const songRequest = /\b(theme song|jingle|anthem|generate\s+(a\s+|the\s+)?(theme\s+)?song|create\s+(a\s+|the\s+)?(theme\s+)?song|make\s+(me\s+)?(a\s+|the\s+)?(theme\s+)?song|compose\s+(a\s+)?song|write\s+(a\s+|the\s+)?song)\b/i.test(String(body.request || ""));
      if (songRequest && (!action || (action as any).type !== "music") && !Object.keys(parsed.changes || {}).length) {
        throw new Error("The user requested an original song. Return action {type:'music', prompt, durationSeconds, lyrics} with concise original lyrics you compose matching their request (upbeat, catchy, energetic as described). Do not ask the user to write lyrics first and never direct them to the manual Lyrics field. Only if they explicitly said they will provide their own specific lyrics and those lyrics are missing may you ask for them in chat.");
      }
      if (action?.type === "music" && "prompt" in action && "lyrics" in action && "durationSeconds" in action) {
        const instrumental = action.instrumental === true || /instrumental|no vocals?|without vocals?|no singing|no voice/i.test(action.prompt);
        if (action.durationSeconds !== null && !instrumental && !action.lyrics.trim()) {
          throw new Error("The short vocal music action is missing lyrics. Put the user's supplied or approved lyrics from recentConversation into action.lyrics verbatim. If the user requested an original song, compose concise original lyrics matching their request and include them in action.lyrics. If the user wants specific lyrics that are unavailable, return action null, needsClarification true, and ask for those lyrics in chat. Never send the user to the manual Lyrics field from an AI task.");
        }
        if (action.lyrics.split(/\r?\n/).some((line: string) => line.length > 200)) throw new Error("Music lyrics must have line breaks, with each line at most 200 characters. Preserve the words of supplied lyrics while adding line breaks.");
      }
      if (raw?.type === "search" && body.searchEvidence) throw new Error("The search is already complete. Use searchEvidence to return changes for the requested pool, with action null. Do not search again.");
      if (raw && !action) throw new Error(`The action ${String(raw.type || "unknown")} is not supported in that format. Edit an existing pool using changes.gameTools with its saved ID; create a new pool using changes.newTools; return action null for these saved edits.`);
      // Edit-layering guards: an editResult turn must move the chain forward.
      // Repeating the step that just completed (same source, same prompt) is
      // a validation error on the first attempt (Muse gets one chance to
      // correct it); if it comes back identical again — or claims a step
      // beyond the five-layer cap — the action is dropped and the chain ends
      // with the reply instead of resubmitting the same edit forever.
      if (editResult && action?.type === "edit-video" && "sourceKey" in action && "prompt" in action && typeof action.prompt === "string") {
        const repeatedStep = action.sourceKey === editResult.sourceKey && action.prompt.trim() === editResult.prompt.trim();
        if (repeatedStep && attempt === 0) throw new Error("That exact video edit step just completed and was saved. Return the NEXT distinct step as an edit-video action against editResult.resultKey, or finish with action null and a brief summary. Never resubmit the completed step.");
        if (repeatedStep || editResult.layer >= 5) action = null;
      }
      if (Array.isArray(parsed.changes.gameTools) && parsed.changes.gameTools.some((tool: any) => !body.project?.gameTools?.some((existing: any) => existing.id === tool.id))) throw new Error("New tools must use the tool action");
      if (body.searchEvidence) parsed.changes = groundedResearchCards(parsed.changes, body.searchEvidence, body.project?.gameTools || [], String(body.request || ""));
      if (Object.keys(parsed.changes).length && Array.isArray(body.project?.assets) && Array.isArray(body.project?.controls) && Array.isArray(body.project?.gameTools)) {
        // Client context omits media URLs; saved storage keys still identify connectable assets.
        const validationProject = { ...body.project, assets: body.project.assets.map((asset: any) => ({ ...asset, url: asset.url || (asset.storageKey ? "saved-asset:" + asset.storageKey : undefined) })) };
        const checked = applyBuildChanges(validationProject, parsed.changes);
        validateSequenceBehavior(validationProject, checked.project, parsed.changes);
        if (checked.warnings.length) throw new Error(checked.warnings.join(" "));
        if (!checked.applied) throw new Error("No requested edit could be applied. Use the exact saved item IDs and the documented changes fields, or ask for the missing information.");
      }
      let reply = typeof parsed.reply === "string" ? parsed.reply.trim() : "";
      const internalRepair = /^(?:corrected (?:the )?(?:json|structure)|gameTools is now|I'll fix this by using the proper|I will fix this by using the proper|I'll fix the control reference)/i;
      if ((action || Object.keys(parsed.changes).length || parsed.needsClarification === true) && internalRepair.test(reply)) {
        // Drop the repair preamble, not a legitimate explanation of JSON or app internals.
        const userFacing = reply.replace(/^[^.!?\n—]*[.—]\s*/, "").replace(/^(?:gameTools is now|using the proper)[^.!?\n]*[.!]\s*/i, "");
        const question = parsed.needsClarification === true ? userFacing.match(/[^.!?\n]*\?/)?.[0]?.trim() : undefined;
        reply = action ? "I will carry out the requested task using the existing project tools." : Object.keys(parsed.changes).length ? "The requested draft changes are prepared; the editor will apply them." : "No draft change has been prepared.";
        if (question && !internalRepair.test(question)) reply += "\n\n" + question;
        else if (parsed.needsClarification === true) throw new Error("Ask the actual missing user-facing task question, without JSON or internal repair details.");
      }
      if (!reply && !action && !Object.keys(parsed.changes).length) throw new Error("Return the requested pool edit and a nonempty reply; the previous response contained neither.");
      const outcome = action ? "action" : Object.keys(parsed.changes).length ? "edit" : parsed.needsClarification === true ? "clarification" : parsed.outcome === "unsupported" ? "unsupported" : "answer";
      // Navigation directive: validated against the progress model and the
      // project itself, so Jewel can only ever direct the creator to a
      // stage, step, or saved item that actually exists for this project.
      const navigate = body.project ? validateNavigate(body.project, (parsed as any).navigate) : null;
      return NextResponse.json({ configured: true, outcome, action, reply, needsClarification: parsed.needsClarification === true, changes: parsed.changes, manualSteps: Array.isArray(parsed.manualSteps) ? parsed.manualSteps.filter((x: unknown) => typeof x === "string").slice(0, 6) : [], ...(navigate ? { navigate } : {}) });
    } catch (validationError) {
      if (attempt === 0) {
        try {
          const retryMessage = await jewelChatCompletion([
            { role: "system", content: DRAFT_SYSTEM + JEWEL_ADDENDUM + JEWEL_LAYERING_ADDENDUM + JEWEL_WORKFLOW_ADDENDUM + JEWEL_GENERATION_ADDENDUM + (talkShow ? JEWEL_TALKSHOW_ADDENDUM : "") },
            { role: "user", content: JSON.stringify(draftContext) },
            { role: "assistant", content: String(message) },
            { role: "user", content: (validationError instanceof Error ? "Correct this missing setting: " + validationError.message + " " : "") + "Return one complete JSON object with reply, changes, manualSteps, needsClarification, action. New sequences MUST omit id. Only existing sequence IDs from executionGuide are allowed when editing. Do not reuse selectedItem.id or a tool ID as a sequence ID. Put writing or a clarification question in reply. Put a requested supported operation in action using exactly its documented type and fields. Do not omit the requested operation or return an empty object. Use changes.newTools for new supported tools or card lists. Use changes.sequences for requested linked actions. Do not invent saved IDs. Include every requested size, position, color and font in the saved settings. Research pool entries require sourceId copied from the supplied searchEvidence and sourceQuote copied exactly from that result summary, with no added facts. Describe the final proposal in plain language, never the validation repair or JSON correction. The application attaches the real source URL. Trivia creation uses the documented trivia action with the requested count and categories." },
          ], { jsonObject: true, temperature: 0, maxTokens: 16384, timeoutMs: 85000 });
          if (retryMessage) { message = retryMessage; continue; }
        } catch {}
      }
      const reason = validationError instanceof Error && validationError.message && !(validationError instanceof SyntaxError) ? validationError.message : "The assistant returned incomplete or invalid JSON.";
      console.warn("Jewel draft validation failed:", reason);
      return NextResponse.json({ error: `I could not apply that request: ${reason} No changes were made.` }, { status: 502 });
    }
  }
}
